package io.github.codexpocket.app;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
public final class ConfigLinksTest {
 interface Work{void run()throws Exception;}static int tests;static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);tests++;System.out.println("PASS "+label);}static void reject(Work work,String label)throws Exception{try{work.run();}catch(Exception expected){check(true,label);return;}throw new AssertionError(label);}
 static String link(String json){return "codexpocket://import#v1."+Base64.getUrlEncoder().withoutPadding().encodeToString(json.getBytes(StandardCharsets.UTF_8));}
 static JSONObject copy(JSONObject p)throws Exception{return new JSONObject(p.toString());}
 public static void main(String[] args)throws Exception{
  KeyPairGenerator gen=KeyPairGenerator.getInstance("EC");gen.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));KeyPair keys=gen.generateKeyPair();String id=IdentityProof.hex(MessageDigest.getInstance("SHA-256").digest(keys.getPublic().getEncoded()));JSONObject identity=new JSONObject().put("id",id).put("key",Base64.getEncoder().encodeToString(keys.getPublic().getEncoded())).put("algorithm","p256-sha256");
  JSONObject discovery=new JSONObject().put("version",1).put("enabled",true).put("revision",1).put("service_type",DiscoveryManifest.TYPE).put("tls_spki","a".repeat(64));JSONObject seed=new JSONObject().put("url","https://192.168.1.2:32851").put("label","LAN").put("kind","lan").put("tls","pinned").put("managed",true).put("source","auto");JSONObject config=new JSONObject().put("type","codex-pocket-config").put("version",1).put("name","test computer").put("config_id","b".repeat(64)).put("server_identity",identity).put("discovery",discovery).put("url",seed.getString("url")).put("endpoints",new JSONArray().put(seed));String raw=link(config.toString());
  check(ConfigLinks.parse(raw).getString("config_id").equals("b".repeat(64)),"pure local bootstrap parse");
  reject(()->ConfigLinks.parse(raw.replace("//import#","//wrong#")),"wrong URI host");reject(()->ConfigLinks.parse(raw.replace("import#","import/#")),"URI path rejected");reject(()->ConfigLinks.parse(raw.replace("import#","import?x=1#")),"URI query rejected");reject(()->ConfigLinks.parse(raw+"="),"base64 padding rejected");reject(()->ConfigLinks.parse(raw.replace("#v1.","#v2.")),"version cannot downgrade");reject(()->ConfigLinks.parse("x".repeat(2401)),"URI size bounded");
  reject(()->ConfigLinks.parse(link(config.toString().replace("\"version\":1","\"version\":1,\"version\":1"))),"duplicate keys rejected");reject(()->StrictJson.object("{\"key\":1,\"k\\u0065y\":2}",100),"escaped duplicate keys rejected");reject(()->StrictJson.object("{\"v\":01}",100),"non-JSON leading zero rejected");reject(()->StrictJson.object("{\"v\":1,}",100),"trailing comma rejected");
  reject(()->StrictJson.utf8(new byte[]{(byte)0xc3,0x28}),"malformed UTF8 rejected");reject(()->StrictJson.object("{\"v\":1e999}",100),"nonfinite numeric value rejected");
  JSONObject unicode=copy(config).put("name","🌳".repeat(80));unicode.getJSONArray("endpoints").getJSONObject(0).put("label","🌳".repeat(40));check(ConfigLinks.parse(link(unicode.toString())).getString("name").codePointCount(0,160)==80,"80-name and 40-label emoji codepoints accepted");reject(()->ConfigLinks.parse(link(copy(unicode).put("name","🌳".repeat(81)).toString())),"81-name codepoints rejected");JSONObject longLabel=copy(config);longLabel.getJSONArray("endpoints").getJSONObject(0).put("label","🌳".repeat(41));reject(()->ConfigLinks.parse(link(longLabel.toString())),"41-label codepoints rejected");
  JSONObject bad=copy(config).put("version",1.5);reject(()->ConfigLinks.parse(link(bad.toString())),"non-integer version rejected");JSONObject badSeed=copy(config);badSeed.getJSONArray("endpoints").getJSONObject(0).put("tls","system").put("source","manual");reject(()->ConfigLinks.parse(link(badSeed.toString())),"bootstrap cannot downgrade TLS policy");JSONObject wrongKey=copy(config);wrongKey.getJSONObject("server_identity").put("id","c".repeat(64));reject(()->ConfigLinks.parse(link(wrongKey.toString())),"signing key fingerprint mismatch");
  JSONObject grant=new JSONObject().put("server_identity",identity).put("discovery",discovery);check(ConfigLinks.samePins(config,grant),"same paired signing and TLS identity");check(!ConfigLinks.samePins(config,new JSONObject().put("server_identity",identity)),"legacy grant cannot silently acquire discovery");JSONObject other=copy(grant);other.getJSONObject("discovery").put("tls_spki","d".repeat(64));check(!ConfigLinks.samePins(config,other),"different TLS pin requires pairing");
  JSONObject pair=new JSONObject().put("type","codex-pocket-pair").put("version",1).put("config_id",config.getString("config_id")).put("expires_at",System.currentTimeMillis()/1000+60).put("revision",1).put("ticket","t".repeat(32)).put("server_identity",identity).put("discovery",discovery).put("url",seed.getString("url")).put("endpoints",new JSONArray().put(seed));ConfigLinks.validatePairing(pair,config);check(true,"signed pairing payload accepted");reject(()->ConfigLinks.validatePairing(copy(pair).put("config_id","0".repeat(64)),config),"response config ID bound");reject(()->ConfigLinks.validatePairing(copy(pair).put("expires_at",1),config),"expired pairing rejected");reject(()->ConfigLinks.validatePairing(copy(pair).put("token","must-never-export"),config),"long term token in config payload rejected");reject(()->ConfigLinks.validatePairing(copy(pair).put("url","http://192.168.1.2:32851"),config),"pairing primary cannot downgrade HTTPS");
  JSONObject full=copy(pair);full.getJSONArray("endpoints").put(new JSONObject().put("url","https://public.example.com").put("label","public").put("kind","public").put("tls","system").put("managed",true).put("source","manual"));ConfigLinks.validatePairing(full,config);check(true,"signed manual system HTTPS preserved without relaxing trust");
  IdentityProof.Pin pin=IdentityProof.pin(id,identity.getString("key"),"p256-sha256");String nonce=IdentityProof.nonce(),payload=pair.toString();Signature signature=Signature.getInstance("SHA256withECDSA");signature.initSign(keys.getPrivate());signature.update(("codex-pocket-config-pair-v1\n"+nonce+"\n"+id+"\n"+payload).getBytes(StandardCharsets.UTF_8));String encoded=Base64.getEncoder().encodeToString(signature.sign());DiscoveryProof.verifyConfig(pin,nonce,1,id,nonce,payload,encoded,true);check(true,"config pair signature domain accepted");reject(()->DiscoveryProof.verifyConfig(pin,nonce,1,id,nonce,payload,encoded,false),"config GET signature cannot substitute pair domain");reject(()->DiscoveryProof.verifyConfig(pin,nonce,1,id,IdentityProof.nonce(),payload,encoded,true),"config response nonce bound");
  System.out.println("PASS TOTAL "+tests);
 }
}
